package com.adventureplanner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.Map;
import java.util.Random;
import net.runelite.api.Skill;
import org.junit.Test;

public class LevelTrainingCatalogTest
{
    @Test
    public void catalogProvidesAtLeastFiveHundredQuantityVariations()
    {
        assertTrue(LevelTrainingCatalog.estimatedVariantCount() >= 500);
    }

    @Test
    public void sharksOnlyAppearAtFishingSeventySix()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        levels.put(Skill.FISHING, 75);
        assertTrue(noTitle(levels, "sharks"));
        levels.put(Skill.FISHING, 76);
        assertTrue(!noTitle(levels, "sharks"));
    }

    @Test
    public void meleeMonsterFollowsStats()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        levels.put(Skill.ATTACK, 10);
        levels.put(Skill.STRENGTH, 10);
        levels.put(Skill.DEFENCE, 10);
        assertEquals("cows", LevelTrainingCatalog.meleeMonster(levels));
        levels.put(Skill.ATTACK, 70);
        levels.put(Skill.STRENGTH, 70);
        levels.put(Skill.DEFENCE, 70);
        assertEquals("Scurrius", LevelTrainingCatalog.meleeMonster(levels));
    }

    @Test
    public void everySkillHasMultipleTrainingChoices()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) levels.put(skill, 86);

        java.util.List<BankTaskCandidate> choices = new ArrayList<>();
        choices.addAll(LevelTrainingCatalog.candidates(
            levels, new ArrayList<>(), 60, new Random(2)));
        choices.addAll(SkillActivityCatalog.candidates(
            levels, new ArrayList<>(), 60));

        for (Skill skill : Skill.values())
        {
            if (skill == Skill.OVERALL) continue;
            long count = choices.stream().filter(choice -> choice.getSkill() == skill).count();
            assertTrue(skill.getName() + " heeft minder dan twee trainingsmethoden", count >= 2);
        }
    }

    private static boolean noTitle(Map<Skill, Integer> levels, String text)
    {
        return LevelTrainingCatalog.candidates(levels, new ArrayList<>(), 30, new Random(1))
            .stream().noneMatch(task -> task.getTitle().contains(text));
    }
    @Test
    public void highLevelConstructionHasSeveralConcreteMethods()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        levels.put(Skill.CONSTRUCTION, 86);
        long methods = LevelTrainingCatalog.candidates(
            levels, new ArrayList<>(), 30, new Random(1)).stream()
            .filter(task -> task.getSkill() == Skill.CONSTRUCTION)
            .count();
        assertTrue(methods >= 4);
    }

    @Test
    public void yewLogsUnlockAtWoodcuttingSixty()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        levels.put(Skill.WOODCUTTING, 59);
        assertTrue(noTitle(levels, "yew logs"));
        levels.put(Skill.WOODCUTTING, 60);
        assertTrue(!noTitle(levels, "yew logs"));
    }

    @Test
    public void highLevelTasksDoNotUseOldGenericTargets()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) levels.put(skill, 86);
        String[] genericTargets = {
            "passende melee-monsters", "passende combat-monsters",
            "monsters met Ranged", "raw food", "Forestry-logs",
            "unstrung bows", "Crafting-items", "metalen items",
            "grimy herbs", "passende targets", "Slayer-targets"
        };
        for (BankTaskCandidate task : LevelTrainingCatalog.candidates(
            levels, new ArrayList<>(), 60, new Random(4)))
        {
            for (String generic : genericTargets)
            {
                assertTrue(task.getTitle(), !task.getTitle().contains(generic));
            }
        }
    }
}

package com.adventureplanner;

public enum WeeklyTaskOption
{
    TEARS("weekly_tears", "Tears of Guthix"),
    KINGDOM("weekly_kingdom", "Kingdom"),
    MINIGAME("weekly_minigame", "Afwisselende minigame"),
    BOSS("weekly_boss", "Boss-opdracht");

    private final String taskId;
    private final String label;

    WeeklyTaskOption(String taskId, String label)
    {
        this.taskId = taskId;
        this.label = label;
    }

    public static boolean isHidden(String taskId, java.util.Set<WeeklyTaskOption> hidden)
    {
        if (hidden == null) return false;
        for (WeeklyTaskOption option : hidden)
        {
            if (option.taskId.equals(taskId)) return true;
        }
        return false;
    }

    @Override
    public String toString()
    {
        return label;
    }
}

package com.adventureplanner;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;

final class SupplyChainCatalog
{
    private SupplyChainCatalog() {}

    static List<BankTaskCandidate> candidates(Map<Skill, Integer> levels,
        Set<Skill> blocked, int minutes, Map<String, Integer> supplies)
    {
        List<BankTaskCandidate> result = new ArrayList<>();
        BankTaskCandidate logs = logPrerequisite(levels, blocked, minutes, supplies);
        if (logs != null) result.add(logs);
        BankTaskCandidate fish = fishingPrerequisite(levels, blocked, minutes, supplies);
        if (fish != null) result.add(fish);
        BankTaskCandidate ore = miningPrerequisite(levels, blocked, minutes, supplies);
        if (ore != null) result.add(ore);
        result.addAll(ProductionSupplyPlanner.candidates(levels, blocked, minutes, supplies));
        return result;
    }

    static BankTaskCandidate prerequisiteFor(Skill goal, Map<Skill, Integer> levels,
        Set<Skill> blocked, int minutes, Map<String, Integer> supplies)
    {
        if (goal == Skill.FLETCHING || goal == Skill.FIREMAKING)
            return logPrerequisite(levels, blocked, minutes, supplies);
        if (goal == Skill.COOKING)
            return fishingPrerequisite(levels, blocked, minutes, supplies);
        if (goal == Skill.SMITHING)
            return miningPrerequisite(levels, blocked, minutes, supplies);
        return ProductionSupplyPlanner.prerequisiteFor(goal, levels, blocked, minutes, supplies);
    }

    private static BankTaskCandidate logPrerequisite(Map<Skill, Integer> levels,
        Set<Skill> blocked, int minutes, Map<String, Integer> supplies)
    {
        int fletching = levels.getOrDefault(Skill.FLETCHING, 1);
        int firemaking = levels.getOrDefault(Skill.FIREMAKING, 1);
        if ((fletching >= 99 && firemaking >= 99) || blocked.contains(Skill.WOODCUTTING)
            || hasAny(supplies, "Logs", "Oak logs", "Willow logs", "Maple logs",
                "Yew logs", "Magic logs")) return null;

        int woodcutting = levels.getOrDefault(Skill.WOODCUTTING, 1);
        int processing = Math.max(fletching < 99 ? fletching : 1,
            firemaking < 99 ? firemaking : 1);
        String logs;
        int rate;
        if (woodcutting >= 75 && processing >= 75)
        {
            logs = "magic logs";
            rate = 55;
        }
        else if (woodcutting >= 60 && processing >= 60)
        {
            logs = "yew logs";
            rate = 80;
        }
        else if (woodcutting >= 45 && processing >= 45)
        {
            logs = "maple logs";
            rate = 150;
        }
        else if (woodcutting >= 30 && processing >= 30)
        {
            logs = "willow logs";
            rate = 220;
        }
        else if (woodcutting >= 15 && processing >= 15)
        {
            logs = "oak logs";
            rate = 180;
        }
        else
        {
            logs = "regular logs";
            rate = 160;
        }
        int amount = scaled(rate, minutes);
        String next = fletching < 99 ? fletchingProduct(fletching) : "Firemaking";
        return new BankTaskCandidate(Skill.WOODCUTTING,
            "Hak " + amount + " " + logs + " voor " + next,
            "Voorraadketen: verzamel exact deze logs; daarna kan de planner ze verwerken");
    }

    private static BankTaskCandidate fishingPrerequisite(Map<Skill, Integer> levels,
        Set<Skill> blocked, int minutes, Map<String, Integer> supplies)
    {
        int cooking = levels.getOrDefault(Skill.COOKING, 1);
        if (cooking >= 99 || blocked.contains(Skill.FISHING)
            || hasRawFish(supplies)) return null;

        int fishing = levels.getOrDefault(Skill.FISHING, 1);
        String fish;
        int rate;
        if (fishing >= 82 && cooking >= 84)
        {
            fish = "raw anglerfish";
            rate = 130;
        }
        else if (fishing >= 62 && cooking >= 62)
        {
            fish = "raw monkfish";
            rate = 300;
        }
        else if (fishing >= 40 && cooking >= 40)
        {
            fish = "raw lobsters";
            rate = 180;
        }
        else if (fishing >= 20 && cooking >= 25)
        {
            fish = "raw trout/salmon";
            rate = 420;
        }
        else
        {
            fish = "raw shrimps";
            rate = 220;
        }
        int amount = scaled(rate, minutes);
        return new BankTaskCandidate(Skill.FISHING,
            "Vang " + amount + " " + fish + " voor Cooking",
            "Voorraadketen: vang exact deze vis; daarna kan de planner hem laten koken");
    }

    private static BankTaskCandidate miningPrerequisite(Map<Skill, Integer> levels,
        Set<Skill> blocked, int minutes, Map<String, Integer> supplies)
    {
        int smithing = levels.getOrDefault(Skill.SMITHING, 1);
        if (smithing >= 99 || blocked.contains(Skill.MINING)
            || hasAny(supplies, "Copper ore", "Tin ore", "Iron ore", "Coal",
                "Bronze bar", "Iron bar", "Steel bar", "Mithril bar")) return null;

        int mining = levels.getOrDefault(Skill.MINING, 1);
        String ore;
        int rate;
        if (mining >= 15 && smithing >= 15)
        {
            ore = "iron ore";
            rate = 650;
        }
        else
        {
            ore = "copper/tin ore (ongeveer half van elk)";
            rate = 300;
        }
        int amount = scaled(rate, minutes);
        return new BankTaskCandidate(Skill.MINING,
            "Mine " + amount + " " + ore + " voor Smithing",
            "Voorraadketen: verzamel exact deze ore; daarna kan de planner bars laten maken");
    }

    private static boolean hasRawFish(Map<String, Integer> supplies)
    {
        for (Map.Entry<String, Integer> entry : supplies.entrySet())
        {
            if (entry.getValue() > 0 && entry.getKey().toLowerCase().startsWith("raw "))
                return true;
        }
        return false;
    }

    private static boolean hasAny(Map<String, Integer> supplies, String... items)
    {
        return TrainingSupplyCatalog.count(supplies, items) > 0;
    }

    private static String fletchingProduct(int level)
    {
        if (level >= 85) return "magic longbows (u)";
        if (level >= 80) return "magic shortbows (u)";
        if (level >= 70) return "yew longbows (u)";
        if (level >= 65) return "yew shortbows (u)";
        if (level >= 55) return "maple longbows (u)";
        if (level >= 50) return "maple shortbows (u)";
        if (level >= 40) return "willow longbows (u)";
        if (level >= 35) return "willow shortbows (u)";
        if (level >= 25) return "oak longbows (u)";
        if (level >= 20) return "oak shortbows (u)";
        return "arrow shafts";
    }
    private static int scaled(int hourly, int minutes)
    {
        int amount = Math.max(10, hourly * minutes / 60);
        return amount < 20 ? amount : (amount / 5) * 5;
    }
}

package com.adventureplanner;

import java.util.Map;
import net.runelite.api.Skill;

final class TrainingSupplyCatalog
{
    private TrainingSupplyCatalog() {}

    /**
     * Returns -1 when the method gathers/provides its own materials, otherwise
     * the maximum number of task units supported by bank plus inventory.
     */
    static int availableUnits(TrainingMethod method, Map<String, Integer> supplies)
    {
        Skill skill = method.getSkill();
        String target = method.getTarget().toLowerCase();

        if (skill == Skill.FLETCHING)
        {
            if (target.contains("arrow shafts")) return count(supplies, "Logs") * 15;
            if (target.contains("oak ") && target.contains("bows")) return count(supplies, "Oak logs");
            if (target.contains("willow ") && target.contains("bows")) return count(supplies, "Willow logs");
            if (target.contains("maple ") && target.contains("bows")) return count(supplies, "Maple logs");
            if (target.contains("yew ") && target.contains("bows")) return count(supplies, "Yew logs");
            if (target.contains("magic ") && target.contains("bows")) return count(supplies, "Magic logs");
            return 0;
        }

        if (skill == Skill.COOKING)
        {
            if (target.contains("jugs of wine"))
            {
                return Math.min(count(supplies, "Grapes"), count(supplies, "Jug of water"));
            }
            if (target.startsWith("raw "))
            {
                return count(supplies, target);
            }
            return 0;
        }

        if (skill == Skill.FIREMAKING)
        {
            if (target.contains("wintertodt")) return -1;
            if (target.contains("regular logs")) return count(supplies, "Logs");
            if (target.contains("oak logs")) return count(supplies, "Oak logs");
            if (target.contains("willow logs")) return count(supplies, "Willow logs");
            if (target.contains("maple logs")) return count(supplies, "Maple logs");
            if (target.contains("yew logs")) return count(supplies, "Yew logs");
            if (target.contains("magic logs")) return count(supplies, "Magic logs");
            return 0;
        }

        if (skill == Skill.SMITHING)
        {
            if (target.contains("bronze bars"))
            {
                return Math.min(count(supplies, "Copper ore"), count(supplies, "Tin ore"));
            }
            if (target.contains("iron bars")) return count(supplies, "Iron ore");
            if (target.contains("iron platebodies")) return count(supplies, "Iron bar") / 5;
            if (target.contains("steel platebodies")) return count(supplies, "Steel bar") / 5;
            if (target.contains("mithril dart tips")) return count(supplies, "Mithril bar") * 10;
            if (target.contains("giants' foundry"))
            {
                return totalBars(supplies) / 20;
            }
            return 0;
        }

        if (skill == Skill.CRAFTING)
        {
            if (target.contains("leather gloves"))
            {
                if (count(supplies, "Needle") <= 0) return 0;
                return Math.min(count(supplies, "Leather"), count(supplies, "Thread") * 5);
            }
            if (target.contains("gold bracelets"))
            {
                return count(supplies, "Bracelet mould") > 0 ? count(supplies, "Gold bar") : 0;
            }
            if (target.contains("sapphire rings"))
            {
                if (count(supplies, "Ring mould") <= 0) return 0;
                return Math.min(count(supplies, "Gold bar"), count(supplies, "Sapphire"));
            }
            if (target.contains("glass orbs"))
            {
                return count(supplies, "Glassblowing pipe") > 0
                    ? count(supplies, "Molten glass") : 0;
            }
            if (target.contains("water battlestaves"))
            {
                return Math.min(count(supplies, "Water orb"), count(supplies, "Battlestaff"));
            }
            if (target.contains("green d'hide bodies"))
            {
                return count(supplies, "Green dragon leather") / 3;
            }
            if (target.contains("black d'hide bodies"))
            {
                return count(supplies, "Black dragon leather") / 3;
            }
            return 0;
        }

        if (skill == Skill.HERBLORE)
        {
            if (target.contains("attack potions") && !target.contains("super"))
            {
                return Math.min(count(supplies, "Guam potion (unf)"),
                    count(supplies, "Eye of newt"));
            }
            if (target.contains("prayer potions"))
            {
                return Math.min(count(supplies, "Ranarr potion (unf)"),
                    count(supplies, "Snape grass"));
            }
            if (target.contains("super attack potions"))
            {
                return Math.min(count(supplies, "Irit potion (unf)"),
                    count(supplies, "Eye of newt"));
            }
            if (target.contains("mixology"))
            {
                return totalCleanHerbs(supplies) / 3;
            }
            if (target.contains("stamina potions"))
            {
                return Math.min(count(supplies, "Super energy(4)"),
                    count(supplies, "Amylase crystal") / 4);
            }
            return 0;
        }

        if (skill == Skill.PRAYER)
        {
            if (target.contains("big bones")) return count(supplies, "Big bones");
            if (target.contains("dragon bones")) return count(supplies, "Dragon bones");
            if (target.contains("calcified deposits"))
            {
                return count(supplies, "Calcified deposit", "Calcified deposits");
            }
            if (target.contains("ensouled goblin heads"))
            {
                return minimum(count(supplies, "Ensouled goblin head"),
                    count(supplies, "Body rune") / 4, count(supplies, "Nature rune") / 2);
            }
            if (target.contains("ensouled demon heads"))
            {
                return minimum(count(supplies, "Ensouled demon head"),
                    count(supplies, "Body rune") / 4, count(supplies, "Nature rune") / 3,
                    count(supplies, "Soul rune"));
            }
            if (target.contains("ensouled aviansie heads"))
            {
                return minimum(count(supplies, "Ensouled aviansie head"), count(supplies, "Blood rune"),
                    count(supplies, "Nature rune") / 3, count(supplies, "Soul rune") / 2);
            }
            if (target.contains("ensouled bloodveld heads"))
            {
                return minimum(count(supplies, "Ensouled bloodveld head"), count(supplies, "Blood rune"),
                    count(supplies, "Nature rune") / 3, count(supplies, "Soul rune") / 2);
            }
            if (target.contains("ensouled dragon heads"))
            {
                return minimum(count(supplies, "Ensouled dragon head"), count(supplies, "Blood rune") / 4,
                    count(supplies, "Nature rune") / 4, count(supplies, "Soul rune") / 2);
            }
            return 0;
        }

        if (skill == Skill.RUNECRAFT)
        {
            if (target.contains("guardians of the rift")) return -1;
            int essence = count(supplies, "Rune essence", "Pure essence", "Daeyalt essence");
            if (target.contains("lava runes"))
            {
                essence = Math.min(essence, count(supplies, "Earth rune"));
            }
            return essence;
        }

        if (skill == Skill.CONSTRUCTION)
        {
            if (target.contains("beginner mahogany homes"))
                return count(supplies, "Plank") / 20;
            if (target.contains("novice mahogany homes"))
                return count(supplies, "Oak plank") / 20;
            if (target.contains("adept mahogany homes"))
                return count(supplies, "Teak plank") / 20;
            if (target.contains("expert mahogany homes"))
                return count(supplies, "Mahogany plank") / 20;
            if (target.contains("oak larders")) return count(supplies, "Oak plank") / 8;
            if (target.contains("mahogany tables")) return count(supplies, "Mahogany plank") / 6;
            if (target.contains("teak garden benches")) return count(supplies, "Teak plank") / 6;
            if (target.contains("poh-upgrades")) return totalPlanks(supplies) / 10;
            return 0;
        }

        return -1;
    }

    static int count(Map<String, Integer> supplies, String... itemNames)
    {
        int amount = 0;
        for (Map.Entry<String, Integer> entry : supplies.entrySet())
        {
            for (String itemName : itemNames)
            {
                if (entry.getKey().equalsIgnoreCase(itemName))
                {
                    amount += Math.max(0, entry.getValue());
                    break;
                }
            }
        }
        return amount;
    }

    private static int totalBars(Map<String, Integer> supplies)
    {
        int amount = 0;
        for (Map.Entry<String, Integer> entry : supplies.entrySet())
        {
            if (entry.getKey().toLowerCase().endsWith(" bar"))
            {
                amount += Math.max(0, entry.getValue());
            }
        }
        return amount;
    }

    private static int totalPlanks(Map<String, Integer> supplies)
    {
        return count(supplies, "Plank", "Oak plank", "Teak plank", "Mahogany plank");
    }

    private static int totalCleanHerbs(Map<String, Integer> supplies)
    {
        int amount = 0;
        for (Map.Entry<String, Integer> entry : supplies.entrySet())
        {
            String name = entry.getKey().toLowerCase();
            if ((name.contains("guam") || name.contains("marrentill")
                || name.contains("tarromin") || name.contains("harralander")
                || name.contains("ranarr") || name.contains("toadflax")
                || name.contains("irit") || name.contains("avantoe")
                || name.contains("kwuarm") || name.contains("snapdragon")
                || name.contains("cadantine") || name.contains("lantadyme")
                || name.contains("dwarf weed") || name.contains("torstol"))
                && !name.startsWith("grimy "))
            {
                amount += Math.max(0, entry.getValue());
            }
        }
        return amount;
    }

    private static int minimum(int... amounts)
    {
        int minimum = Integer.MAX_VALUE;
        for (int amount : amounts)
        {
            minimum = Math.min(minimum, amount);
        }
        return minimum == Integer.MAX_VALUE ? 0 : minimum;
    }
}

