package com.adventureplanner;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;

/**
 * Exact refill tasks for production skills whose inputs are not covered by the
 * basic log, fish and ore chains.
 */
final class ProductionSupplyPlanner
{
    private ProductionSupplyPlanner() {}

    static List<BankTaskCandidate> candidates(Map<Skill, Integer> levels,
        Set<Skill> blocked, int minutes, Map<String, Integer> supplies)
    {
        List<BankTaskCandidate> result = new ArrayList<>();
        add(result, crafting(levels, blocked, minutes, supplies));
        add(result, herblore(levels, blocked, minutes, supplies));
        add(result, prayer(levels, blocked, minutes, supplies));
        add(result, runecraft(levels, blocked, minutes, supplies));
        add(result, construction(levels, blocked, minutes, supplies));
        return result;
    }

    static BankTaskCandidate prerequisiteFor(Skill goal, Map<Skill, Integer> levels,
        Set<Skill> blocked, int minutes, Map<String, Integer> supplies)
    {
        if (goal == Skill.CRAFTING) return crafting(levels, blocked, minutes, supplies);
        if (goal == Skill.HERBLORE) return herblore(levels, blocked, minutes, supplies);
        if (goal == Skill.PRAYER) return prayer(levels, blocked, minutes, supplies);
        if (goal == Skill.RUNECRAFT) return runecraft(levels, blocked, minutes, supplies);
        if (goal == Skill.CONSTRUCTION) return construction(levels, blocked, minutes, supplies);
        return null;
    }

    private static BankTaskCandidate crafting(Map<Skill, Integer> levels, Set<Skill> blocked,
        int minutes, Map<String, Integer> supplies)
    {
        int level = levels.getOrDefault(Skill.CRAFTING, 1);
        if (level >= 99 || hasCraftingInputs(supplies)) return null;
        int amount = scaled(level >= 46 ? 650 : 220, minutes);
        if (level >= 63 && !blocked.contains(Skill.ATTACK))
        {
            String colour = level >= 84 ? "black" : "green";
            return new BankTaskCandidate(Skill.ATTACK,
                "Verzamel " + amount + " " + colour + " dragonhides voor d'hide bodies",
                "Laat de hides daarna tanen; 3 leather per body - exacte Crafting-voorraad");
        }
        if (level >= 46 && !blocked.contains(Skill.MINING))
        {
            return new BankTaskCandidate(Skill.MINING,
                "Verzamel " + amount + " buckets of sand en giant seaweed voor glass orbs",
                "Smelt 6 sand met 1 giant seaweed tot molten glass; bewaar een glassblowing pipe");
        }
        if (level >= 7 && !blocked.contains(Skill.MINING))
        {
            return new BankTaskCandidate(Skill.MINING,
                "Mine " + amount + " gold ore voor gold bracelets",
                "Smelt de ore tot gold bars; bewaar een bracelet mould voor het eindproduct");
        }
        if (!blocked.contains(Skill.ATTACK))
        {
            return new BankTaskCandidate(Skill.ATTACK,
                "Verzamel " + amount + " cowhides voor leather gloves",
                "Laat de hides tanen tot leather; bewaar needle en thread");
        }
        return null;
    }

    private static BankTaskCandidate herblore(Map<Skill, Integer> levels, Set<Skill> blocked,
        int minutes, Map<String, Integer> supplies)
    {
        int level = levels.getOrDefault(Skill.HERBLORE, 1);
        if (level >= 99 || hasHerbloreInputs(supplies)) return null;
        int amount = scaled(80, minutes);
        String herb;
        String secondary;
        String product;
        if (level >= 77)
        {
            herb = "avantoe";
            secondary = "mort myre fungi";
            product = "super energy en daarna stamina potions";
        }
        else if (level >= 45)
        {
            herb = "irit";
            secondary = "eyes of newt";
            product = "super attack potions";
        }
        else if (level >= 38)
        {
            herb = "ranarr";
            secondary = "snape grass";
            product = "prayer potions";
        }
        else
        {
            herb = "guam";
            secondary = "eyes of newt";
            product = "attack potions";
        }
        Skill source = !blocked.contains(Skill.FARMING) ? Skill.FARMING : Skill.ATTACK;
        if (blocked.contains(source)) return null;
        return new BankTaskCandidate(source,
            "Verzamel " + amount + " " + herb + " herbs en " + amount + " " + secondary,
            "Exacte Herblore-voorraad voor " + product + "; gebruik herb-runs en bank eerst");
    }

    private static BankTaskCandidate prayer(Map<Skill, Integer> levels, Set<Skill> blocked,
        int minutes, Map<String, Integer> supplies)
    {
        int prayer = levels.getOrDefault(Skill.PRAYER, 1);
        int magic = levels.getOrDefault(Skill.MAGIC, 1);
        if (prayer >= 99 || magic < 16 || hasPrayerInputs(supplies)
            || blocked.contains(Skill.ATTACK)) return null;
        int amount = Math.max(5, minutes / 3);
        String head;
        String runes;
        if (magic >= 90)
        {
            head = "ensouled dragon heads";
            runes = (amount * 4) + " blood, " + (amount * 4) + " nature en "
                + (amount * 2) + " soul runes";
        }
        else if (magic >= 72)
        {
            head = "ensouled bloodveld heads";
            runes = amount + " blood, " + (amount * 3) + " nature en "
                + (amount * 2) + " soul runes";
        }
        else if (magic >= 41)
        {
            head = "ensouled demon heads";
            runes = (amount * 4) + " body, " + (amount * 3) + " nature en "
                + amount + " soul runes";
        }
        else
        {
            head = "ensouled goblin heads";
            runes = (amount * 4) + " body en " + (amount * 2) + " nature runes";
        }
        return new BankTaskCandidate(Skill.ATTACK,
            "Verzamel " + amount + " " + head + " voor Prayer",
            "Reanimate daarna in Arceuus; neem totaal " + runes + " mee");
    }

    private static BankTaskCandidate runecraft(Map<Skill, Integer> levels, Set<Skill> blocked,
        int minutes, Map<String, Integer> supplies)
    {
        int level = levels.getOrDefault(Skill.RUNECRAFT, 1);
        if (level >= 99 || TrainingSupplyCatalog.count(supplies,
            "Rune essence", "Pure essence", "Daeyalt essence") > 0
            || blocked.contains(Skill.MINING)) return null;
        int amount = scaled(500, minutes);
        String essence = levels.getOrDefault(Skill.MINING, 1) >= 60
            ? "daeyalt essence" : "rune essence";
        return new BankTaskCandidate(Skill.MINING,
            "Mine " + amount + " " + essence + " voor Runecraft",
            "Vul de bank exact aan; daarna kiest de planner een passende rune op je level");
    }

    private static BankTaskCandidate construction(Map<Skill, Integer> levels, Set<Skill> blocked,
        int minutes, Map<String, Integer> supplies)
    {
        int level = levels.getOrDefault(Skill.CONSTRUCTION, 1);
        if (level >= 99 || hasPlanks(supplies) || blocked.contains(Skill.WOODCUTTING)) return null;
        int woodcutting = levels.getOrDefault(Skill.WOODCUTTING, 1);
        String log = "regular logs";
        String plank = "planks";
        String product = "Beginner Mahogany Homes";
        if (level >= 70 && woodcutting >= 50)
        {
            log = "mahogany logs";
            plank = "mahogany planks";
            product = "Expert Mahogany Homes";
        }
        else if (level >= 50 && woodcutting >= 35)
        {
            log = "teak logs";
            plank = "teak planks";
            product = "Adept Mahogany Homes";
        }
        else if (level >= 20 && woodcutting >= 15)
        {
            log = "oak logs";
            plank = "oak planks";
            product = level >= 33 ? "oak larders" : "Novice Mahogany Homes";
        }
        int amount = scaled(180, minutes);
        return new BankTaskCandidate(Skill.WOODCUTTING,
            "Hak " + amount + " " + log + " en maak " + amount + " " + plank,
            "Exacte Construction-voorraad voor " + product + "; gebruik de sawmill");
    }

    private static boolean hasCraftingInputs(Map<String, Integer> supplies)
    {
        return TrainingSupplyCatalog.count(supplies, "Leather", "Gold bar", "Molten glass",
            "Water orb", "Green dragon leather", "Black dragon leather") > 0;
    }

    private static boolean hasHerbloreInputs(Map<String, Integer> supplies)
    {
        return TrainingSupplyCatalog.count(supplies, "Guam potion (unf)", "Ranarr potion (unf)",
            "Irit potion (unf)", "Super energy(4)") > 0;
    }

    private static boolean hasPrayerInputs(Map<String, Integer> supplies)
    {
        return TrainingSupplyCatalog.count(supplies, "Big bones", "Dragon bones",
            "Calcified deposit", "Calcified deposits", "Ensouled goblin head",
            "Ensouled demon head", "Ensouled aviansie head", "Ensouled bloodveld head", "Ensouled dragon head") > 0;
    }

    private static boolean hasPlanks(Map<String, Integer> supplies)
    {
        return TrainingSupplyCatalog.count(supplies, "Plank", "Oak plank",
            "Teak plank", "Mahogany plank") > 0;
    }

    private static int scaled(int hourly, int minutes)
    {
        int amount = Math.max(10, hourly * minutes / 60);
        return amount < 20 ? amount : amount / 5 * 5;
    }

    private static void add(List<BankTaskCandidate> result, BankTaskCandidate task)
    {
        if (task != null) result.add(task);
    }
}

package com.adventureplanner;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public final class AdventurePlannerOverlay extends Overlay
{
    private final AdventurePlannerConfig config;
    private final PlannerState state;
    private final PanelComponent panel = new PanelComponent();

    public AdventurePlannerOverlay(AdventurePlannerPlugin plugin, AdventurePlannerConfig config,
        PlannerState state)
    {
        super(plugin);
        this.config = config;
        this.state = state;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        panel.setPreferredSize(new Dimension(190, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showGameOverlay()) return null;
        panel.getChildren().clear();
        panel.getChildren().add(TitleComponent.builder()
            .text("Adventure Planner")
            .color(new Color(232, 160, 48))
            .build());

        GeneratedTask task = state.currentGeneratedTask();
        long now = System.currentTimeMillis();
        if (task == null)
        {
            panel.getChildren().add(LineComponent.builder().left(t("Nog geen actieve taak")).build());
        }
        else
        {
            panel.getChildren().add(LineComponent.builder()
                .left(task.getDisplayPhase(config.language())).leftColor(new Color(190, 190, 190)).build());
            addWrappedTaskTitle(task.getDisplayTitle(config.language()));
            int target = task.getTargetAmount();
            if (target > 0)
            {
                int progress = Math.min(target, state.currentTaskProgress());
                boolean complete = progress >= target;
                panel.getChildren().add(LineComponent.builder().left(t("Voortgang"))
                    .right(progress + " / " + target + (complete ? " " + t("KLAAR") : ""))
                    .rightColor(complete ? new Color(91, 173, 112) : new Color(232, 160, 48)).build());
            }
            long taskEndsAt = state.currentTaskEndsAt();
            if (taskEndsAt > 0L)
            {
                boolean expired = taskEndsAt <= now;
                panel.getChildren().add(LineComponent.builder().left(t("Taaktijd"))
                    .right(expired ? "00:00:00" : taskRemaining(taskEndsAt - now))
                    .rightColor(expired ? new Color(214, 103, 85) : new Color(91, 173, 112)).build());
            }
        }

        RunLocation next = null;
        long nextReady = Long.MAX_VALUE;
        for (RunLocation location : RunLocationCatalog.locations())
        {
            if (!visible(location.getType())) continue;
            long readyAt = state.activityReadyAt(location.timerId());
            if (readyAt > now && readyAt < nextReady)
            {
                next = location;
                nextReady = readyAt;
            }
        }
        if (next != null)
        {
            panel.getChildren().add(LineComponent.builder()
                .left(t("Volgende timer"))
                .right(next.getName() + " " + remaining(nextReady - now))
                .rightColor(new Color(91, 173, 112)).build());
        }
        return panel.render(graphics);
    }

    private String t(String text)
    {
        return PlannerText.translate(config.language(), text);
    }

    private void addWrappedTaskTitle(String title)
    {
        StringBuilder line = new StringBuilder();
        for (String word : title.split(" "))
        {
            if (line.length() > 0 && line.length() + word.length() + 1 > 25)
            {
                panel.getChildren().add(LineComponent.builder().left(line.toString()).build());
                line.setLength(0);
            }
            if (line.length() > 0) line.append(' ');
            line.append(word);
        }
        if (line.length() > 0)
        {
            panel.getChildren().add(LineComponent.builder().left(line.toString()).build());
        }
    }

    private static String taskRemaining(long millis)
    {
        long totalSeconds = Math.max(0L, (millis + 999L) / 1000L);
        return String.format("%02d:%02d:%02d", totalSeconds / 3600L,
            totalSeconds % 3600L / 60L, totalSeconds % 60L);
    }

    private boolean visible(RunType type)
    {
        switch (type)
        {
            case HERB: return config.showHerbRuns();
            case TREE: return config.showTreeRuns();
            case BIRDHOUSE: return config.showBirdhouses();
            case SEAWEED: return config.showSeaweedRuns();
            default: return false;
        }
    }

    private static String remaining(long millis)
    {
        long total = Math.max(1, (millis + 59_999L) / 60_000L);
        return total >= 60 ? total / 60 + "u " + total % 60 + "m" : total + "m";
    }
}

package com.adventureplanner;

import java.util.List;
import java.util.Random;

final class ProfitAwareTaskSelector
{
    private ProfitAwareTaskSelector() {}

    static BankTaskCandidate select(List<BankTaskCandidate> candidates,
        Random random, ItemPriceProvider prices)
    {
        int[] margins = new int[candidates.size()];
        boolean[] known = new boolean[candidates.size()];
        int totalWeight = 0;
        int[] weights = new int[candidates.size()];
        for (int i = 0; i < candidates.size(); i++)
        {
            Integer margin = marginPerUnit(candidates.get(i), prices);
            if (margin != null)
            {
                known[i] = true;
                margins[i] = margin;
                weights[i] = margin >= 0 ? 6 : 1;
            }
            else
            {
                weights[i] = 2;
            }
            totalWeight += weights[i];
        }

        int roll = random.nextInt(Math.max(1, totalWeight));
        int selectedIndex = 0;
        for (int i = 0; i < weights.length; i++)
        {
            roll -= weights[i];
            if (roll < 0)
            {
                selectedIndex = i;
                break;
            }
        }

        BankTaskCandidate selected = candidates.get(selectedIndex);
        if (!known[selectedIndex]) return selected;
        int margin = margins[selectedIndex];
        String economy = margin >= 0
            ? "geschatte GE-winst: +" + margin + " gp per eindproduct"
            : "geschatte GE-kosten: " + Math.abs(margin) + " gp per eindproduct";
        return new BankTaskCandidate(selected.getSkill(), selected.getTitle(),
            selected.getDetail() + " - " + economy);
    }

    static Integer marginPerUnit(BankTaskCandidate task, ItemPriceProvider prices)
    {
        String title = task.getTitle().toLowerCase();

        Integer bow = bowMargin(title, prices);
        if (bow != null) return bow;

        if (title.contains("jug of wine"))
            return margin(prices, "Jug of wine", "Grapes", "Jug of water");
        if (title.contains("raw shrimps"))
            return margin(prices, "Shrimps", "Raw shrimps");
        if (title.contains("raw salmon"))
            return margin(prices, "Salmon", "Raw salmon");
        if (title.contains("raw lobster"))
            return margin(prices, "Lobster", "Raw lobster");
        if (title.contains("raw monkfish"))
            return margin(prices, "Monkfish", "Raw monkfish");
        if (title.contains("raw shark"))
            return margin(prices, "Shark", "Raw shark");
        if (title.contains("raw anglerfish"))
            return margin(prices, "Anglerfish", "Raw anglerfish");

        if (title.contains("bronze bars"))
            return margin(prices, "Bronze bar", "Copper ore", "Tin ore");
        if (title.contains("iron bars"))
            return margin(prices, "Iron bar", "Iron ore");
        if (title.contains("iron platebodies"))
            return marginWithInputCount(prices, "Iron platebody", "Iron bar", 5);
        if (title.contains("steel platebodies"))
            return marginWithInputCount(prices, "Steel platebody", "Steel bar", 5);
        if (title.contains("mithril dart tips"))
            return marginPerTen(prices, "Mithril dart tip", "Mithril bar");

        if (title.contains("gold bracelets"))
            return margin(prices, "Gold bracelet", "Gold bar");
        if (title.contains("sapphire rings"))
            return margin(prices, "Sapphire ring", "Gold bar", "Sapphire");
        if (title.contains("glass orbs"))
            return margin(prices, "Unpowered orb", "Molten glass");
        if (title.contains("water battlestaves"))
            return margin(prices, "Water battlestaff", "Water orb", "Battlestaff");
        if (title.contains("green d'hide bodies"))
            return marginWithInputCount(prices, "Green d'hide body", "Green dragon leather", 3);
        if (title.contains("black d'hide bodies"))
            return marginWithInputCount(prices, "Black d'hide body", "Black dragon leather", 3);

        if (title.contains("attack potions") && !title.contains("super"))
            return margin(prices, "Attack potion(3)", "Guam potion (unf)", "Eye of newt");
        if (title.contains("prayer potions"))
            return margin(prices, "Prayer potion(3)", "Ranarr potion (unf)", "Snape grass");
        if (title.contains("super attack potions"))
            return margin(prices, "Super attack(3)", "Irit potion (unf)", "Eye of newt");
        if (title.contains("stamina potions"))
            return marginWithInputs(prices, "Stamina potion(4)",
                new String[] {"Super energy(4)", "Amylase crystal"},
                new int[] {1, 4});

        return null;
    }

    private static Integer bowMargin(String title, ItemPriceProvider prices)
    {
        if (title.contains("oak shortbows (u)"))
            return margin(prices, "Oak shortbow (u)", "Oak logs");
        if (title.contains("willow shortbows (u)"))
            return margin(prices, "Willow shortbow (u)", "Willow logs");
        if (title.contains("maple shortbows (u)"))
            return margin(prices, "Maple shortbow (u)", "Maple logs");
        if (title.contains("yew shortbows (u)"))
            return margin(prices, "Yew shortbow (u)", "Yew logs");
        if (title.contains("magic shortbows (u)"))
            return margin(prices, "Magic shortbow (u)", "Magic logs");
        if (title.contains("oak longbows (u)"))
            return margin(prices, "Oak longbow (u)", "Oak logs");
        if (title.contains("willow longbows (u)"))
            return margin(prices, "Willow longbow (u)", "Willow logs");
        if (title.contains("maple longbows (u)"))
            return margin(prices, "Maple longbow (u)", "Maple logs");
        if (title.contains("yew longbows (u)"))
            return margin(prices, "Yew longbow (u)", "Yew logs");
        if (title.contains("magic longbows (u)"))
            return margin(prices, "Magic longbow (u)", "Magic logs");
        return null;
    }

    private static Integer margin(ItemPriceProvider prices, String output, String... inputs)
    {
        int outputPrice = prices.price(output);
        if (outputPrice <= 0) return null;
        int inputPrice = 0;
        for (String input : inputs)
        {
            int price = prices.price(input);
            if (price <= 0) return null;
            inputPrice += price;
        }
        return outputPrice - inputPrice;
    }

    private static Integer marginWithInputCount(ItemPriceProvider prices,
        String output, String input, int inputCount)
    {
        return marginWithInputs(prices, output, new String[] {input}, new int[] {inputCount});
    }

    private static Integer marginPerTen(ItemPriceProvider prices,
        String output, String input)
    {
        int outputPrice = prices.price(output);
        int inputPrice = prices.price(input);
        if (outputPrice <= 0 || inputPrice <= 0) return null;
        return outputPrice - inputPrice / 10;
    }

    private static Integer marginWithInputs(ItemPriceProvider prices, String output,
        String[] inputs, int[] counts)
    {
        int outputPrice = prices.price(output);
        if (outputPrice <= 0) return null;
        int inputPrice = 0;
        for (int i = 0; i < inputs.length; i++)
        {
            int price = prices.price(inputs[i]);
            if (price <= 0) return null;
            inputPrice += price * counts[i];
        }
        return outputPrice - inputPrice;
    }
}

