    private static String remaining(long millis)
    {
        long totalMinutes = Math.max(1, (millis + 59_999L) / 60_000L);
        long hours = totalMinutes / 60;
        long minutes = totalMinutes % 60;
        return hours > 0 ? hours + "u " + minutes + "m" : minutes + "m";
    }

